    82	function applyStrikeThrough(children) {
    83	    return React.Children.map(children, (child) => {
    84	        if (!React.isValidElement(child)) {
    85	            return child;
    86	        }
    87	        const props = {style: StyleUtils.combineStyles(child.props.style, styles.offlineFeedback.deleted, styles.userSelectNone)};
